/**
 * `npm run gen:domains`: regenerate src/parsers/github-domains.generated.ts (the offline
 * fallback GitHub allowlist) from api.github.com/meta .domains.actions.
 *
 * Deliberately NOT part of the build: `npm run package` and CI stay offline and deterministic.
 * Regeneration is a separate step (by hand or the weekly update-github-domains workflow, which
 * opens a PR) and the diff of the generated file is the review.
 */

import * as fs from 'fs';
import * as path from 'path';

export const GENERATED_FILE = path.join('src', 'parsers', 'github-domains.generated.ts');

/**
 * `.domains.actions` verbatim (strings only, de-duplicated, meta's order). Deliberately no
 * normalisation or filtering here: github-parser.ts applies exactly the same runtime checks to
 * this snapshot as to the live list.
 */
export function generatedDomains(actions: unknown[]): string[] {
  return Array.from(new Set(actions.filter((d): d is string => typeof d === 'string')));
}

export function renderGeneratedFile(domains: string[], date: string): string {
  return (
    `// GENERATED by \`npm run gen:domains\` from api.github.com/meta .domains.actions on ${date}\n` +
    '// - do not edit by hand. Verbatim; github-parser.ts normalises it like the live list (offline fallback).\n\n' +
    'export const GITHUB_ACTIONS_DOMAINS: readonly string[] = [\n' +
    // JSON.stringify: an entry is data, never code, whatever meta returns (prettier re-quotes)
    domains.map(d => `  ${JSON.stringify(d)}`).join(',\n') +
    '\n];\n'
  );
}

async function main(): Promise<void> {
  const headers: Record<string, string> = {
    accept: 'application/vnd.github+json',
    'user-agent': 'safer-runner-action gen:domains'
  };
  if (process.env.GITHUB_TOKEN) headers.authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  const res = await fetch('https://api.github.com/meta', { headers });
  if (!res.ok) throw new Error(`api.github.com/meta: HTTP ${res.status}`);
  const actions = ((await res.json()) as { domains?: { actions?: unknown } }).domains?.actions;
  if (!Array.isArray(actions) || actions.length === 0) throw new Error('api.github.com/meta: no .domains.actions');
  const domains = generatedDomains(actions);
  fs.writeFileSync(GENERATED_FILE, renderGeneratedFile(domains, new Date().toISOString().slice(0, 10)));
  console.log(`${GENERATED_FILE}: ${domains.length} domains`);
}

if (require.main === module) {
  main().catch(e => {
    console.error(e);
    process.exit(1);
  });
}
